import { useState, useMemo } from 'react';

export function ProductList({ products }: { products: { id: number; price: number }[] }) {
  const [maxPrice, setMaxPrice] = useState(100);

  // Heavy filter + sort runs ONLY when products or maxPrice changes
  const filteredProducts = useMemo(() => {
    return products
      .filter(p => p.price <= maxPrice)
      .sort((a, b) => b.price - a.price);
  }, [products, maxPrice]);

  return <div>Filtered Count: {filteredProducts.length}</div>;
}

import { useState, useCallback, memo } from 'react';

// Child component memoized
const MemoizedButton = memo(({ onClick }: { onClick: () => void }) => {
  console.log('Button rendered!');
  return <button onClick={onClick}>Click Me</button>;
});

export function Parent() {
  const [count, setCount] = useState(0);

  // useCallback keeps onClick reference stable across count re-renders
  const handleClick = useCallback(() => {
    console.log('Button clicked');
  }, []); // Empty deps = stable reference forever

  return (
    <div>
      <p>Parent Count: {count}</p>
      <button onClick={() => setCount(c => c + 1)}>Increment Parent</button>
      <MemoizedButton onClick={handleClick} />
    </div>
  );
}

import { createContext, useContext, useState, useMemo, ReactNode } from 'react';

interface ThemeContextType { theme: string; toggleTheme: () => void; }
const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState('light');
  const toggleTheme = () => setTheme(t => t === 'light' ? 'dark' : 'light');

  // Memoize provider value to prevent extra child re-renders
  const value = useMemo(() => ({ theme, toggleTheme }), [theme]);

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

export function ThemeButton() {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('ThemeButton must be inside ThemeProvider');
  return <button onClick={context.toggleTheme}>Current Theme: {context.theme}</button>;
}

import { useState, useEffect } from 'react';

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      return initialValue;
    }
  });

  useEffect(() => {
    window.localStorage.setItem(key, JSON.stringify(storedValue));
  }, [key, storedValue]);

  return [storedValue, setStoredValue] as const;
}

import { useState, FormEvent, ChangeEvent } from 'react';

export function LoginForm() {
  const [formData, setFormData] = useState({ email: '', password: '' });

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault(); // Stop page reload!
    console.log('Submitted:', formData);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="email" value={formData.email} onChange={handleChange} placeholder="Email" />
      <input name="password" type="password" value={formData.password} onChange={handleChange} placeholder="Password" />
      <button type="submit">Login</button>
    </form>
  );
}

import { useRef, FormEvent } from 'react';

export function UncontrolledForm() {
  const nameRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    alert(`Submitted Name: ${nameRef.current?.value}`); // Read directly from DOM ref
  };

  return (
    <form onSubmit={handleSubmit}>
      {/* defaultValue initializes input without controlling value prop */}
      <input ref={nameRef} defaultValue="John Doe" />
      <button type="submit">Submit</button>
    </form>
  );
}

