import { memo } from 'react';

interface UserProps { id: number; name: string; details: { age: number } }

// Custom comparator returns true to SKIP render when id and name match
export const UserRow = memo(
  function UserRow({ id, name }: UserProps) {
    console.log(`Rendered UserRow ${id}`);
    return <div>{name}</div>;
  },
  (prevProps, nextProps) => {
    return prevProps.id === nextProps.id && prevProps.name === nextProps.name;
  }
);

